INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('(CS)²AI Online™ Seminar: Cybersecurity Vulnerability Reporting & Remediation', 'Los Angeles Cyber Security for Control Systems', 'Tech & Software', 'Last year Billy and his team hacked a connected wheelchair and sent it careening down a flight of stairs. Recently the manufacturer issued', 'Last year Billy and his team hacked a connected wheelchair and sent it careening down a flight of stairs. Recently the manufacturer issued a patch to its customers that addresses the authentication and encryption weaknesses we exploited. The update has received 510(k) clearance from the FDA, and the patch is cleared for installation on devices. Thus, the circle is complete, the bugs are no more, and the issues we found have been mitigated. The time between public notification and patch release More info: https://www.meetup.com/los-angeles-cyber-security-for-control-systems/events/316909568/', '2026-10-21T10:00:00-07:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 33.97, -118.24, 'Los Angeles Cyber Security for Control Systems', 0, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/los-angeles-cyber-security-for-control-systems/events/316909568/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
