INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Scruteon and Glendale Rotary Scam Awareness Workshop', 'Los Angeles Financial Freedom Pathfinders', 'Real Estate', 'Scam prevention workshop with practical tips to spot scams, protect yourself, and understand emerging AI threats like deepfakes. Join us', 'Scam prevention workshop with practical tips to spot scams, protect yourself, and understand emerging AI threats like deepfakes. Join us for an interactive **Scam Prevention & Awareness Workshop** featuring practical, actionable tips to help you recognize common scams, avoid falling victim, and respond effectively when something seems suspicious. The workshop will cover: 🚨 Common scams and warning signs to watch for 🔐 Practical steps for protecting your personal information and accounts 🤖 More info: https://www.meetup.com/los-angeles-gain-freedom-from-time-money-meetup-group/events/316862309/', '2026-10-22T18:00:00-07:00', 'Adventist Health Glendale', '1509 Wilson Terrace, Glendale, CA 91206, USA', 'Glendale', 'CA', '91206', 34.14899425061, -118.229509244066, 'Los Angeles Financial Freedom Pathfinders', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/los-angeles-gain-freedom-from-time-money-meetup-group/events/316862309/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Social Happy Hour | Studio City', 'Los Angeles Financial Freedom Pathfinders', 'Real Estate', '***Step Further Into 2026 With Insight, Opportunity & the Right Network*** Reset your strategy for the months ahead at the **Real Estate', '***Step Further Into 2026 With Insight, Opportunity & the Right Network*** Reset your strategy for the months ahead at the **Real Estate Social Happy Hour** on **October 27th** in **Studio City**. Meet professionals and investors for high-impact conversations, actionable insights, and meaningful relationships that help deals happen. **Why Attend:** ⚡ Real-world strategies—no fluff 🤝 High-level networking with doers and decision-makers 🔍 Insights on what’s working in today’s market Our Studio More info: https://www.meetup.com/los-angeles-gain-freedom-from-time-money-meetup-group/events/316892566/', '2026-10-27T18:30:00-07:00', 'Laurel Tavern', '11938 Ventura Blvd', 'Studio City', 'CA', '', 33.97, -118.24, 'Los Angeles Financial Freedom Pathfinders', 2, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/los-angeles-gain-freedom-from-time-money-meetup-group/events/316892566/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
